const url = "https://raw.githubusercontent.com/jasonbitsmith/muse-skills/main/README.md";
const cfg = { url: url, proxy: "127.0.0.1", port: 7897 };
const js = [
  "const http=require('http');",
  "const cfg=" + JSON.stringify(cfg) + ";",
  "const pu=new URL(cfg.url);",
  "http.get({host:cfg.proxy,port:cfg.port,path:cfg.url,headers:{Host:pu.host,'User-Agent':'Mozilla/5.0 Chrome/131'}},function(res){",
  "  const c=[];res.on('data',function(d){c.push(d)});",
  "  res.on('end',function(){",
  "    const s=Buffer.concat(c).toString('utf8');",
  "    console.log('LEN',s.length);",
  "    // extract student-section",
  "    const i=s.indexOf('学生党');",
  "    console.log('学生党 idx:',i);",
  "    if(i>0){ console.log('--- STUDENT SECTION ---'); console.log(s.substring(i-200, i+3000)); }",
  "    const j=s.indexOf('赚钱与副业');",
  "    if(j>0){ console.log('--- MONEY SECTION ---'); console.log(s.substring(j-100, j+2500)); }",
  "  });",
  "});",
].join("\n");
await tools.write({ file_path: "C:/Users/jjq21/AppData/Local/Temp/ofm-d2.cjs", content: js });
const f = "C:/Users/jjq21/AppData/Local/Temp/ofm-d2.cjs";
const r = await tools.pwsh({ command: "node " + JSON.stringify(f), description: "Fetch muse-skills raw README and extract sections", timeoutMs: 200000 });
console.log(r.kind === "foreground" ? (r.stdout.text + r.stderr.text) : JSON.stringify(r).slice(0, 9000));
